    function parseTextToWorkbook(text) {
        var lines = text.split(/\r\n|\n/);
        var rows = [];
        for (var i = 0; i < lines.length; i++) {
            var line = lines[i].trim();
            if (!line) continue;
            var parts = line.split(/[,;\t]/);
            rows.push(parts);
        }
        return {
            SheetNames: ['Sheet1'],
            Sheets: {
                'Sheet1': rows
            }
        };
    }

